import { describe, it, expect, vi } from 'vitest'
import { proxy, middleware } from './proxy'

describe('proxy middleware', () => {
  it('adds X-Request-Id header and logs pathname', () => {
    const consoleSpy = vi.spyOn(console, 'log').mockImplementation(() => {})
    const req = {
      nextUrl: { pathname: '/test-path' },
      url: 'http://localhost:3000/test-path',
    } as any

    const res = proxy(req)
    expect(consoleSpy).toHaveBeenCalledWith('/test-path')
    expect(res.headers.get('X-Request-Id')).toBeDefined()
    expect(typeof res.headers.get('X-Request-Id')).toBe('string')
    expect(res.headers.get('X-Request-Id')?.length).toBeGreaterThan(0)
    consoleSpy.mockRestore()
  })
})

